local function order(c)
    local es={};
    for e in pairs(c) do
        es[#es+1]=e
    end;
    table.sort(es);
    if not c.C then
        return es
    end;
    local out={'C'};
    if c.H then
        out[#out+1]='H'
    end;
    for _,e in ipairs(es) do
        if e~='C' and e~='H' then
            out[#out+1]=e
        end
    end;
    return out
local function hill(c,q)
    local t={};
    for _,e in ipairs(order(c)) do
        t[#t+1]=e..(c[e]==1 and '' or c[e])
    end;
    q=q or 0;
    return table.concat(t)..(q==0 and '' or '^'..(math.abs(q)==1 and '' or math.abs(q))..(q>0 and '+' or '-'))
    local ok,f=pcall(function()
        local c=sequence();
        while peek()=='.' do
            p=p+1;
            local k=number();
            add(c,sequence(),k)
        end;
        local q=0;
        if peek()=='^' then
            p=p+1;
            local k=number();
            local ch=peek();
            if ch~='+' and ch~='-' then
                error('syntax')
            end;
            p=p+1;
            q=ch=='+' and k or -k
        end;
        if p~=#text+1 then
            error('syntax')
        end;
        return {c=c,q=q}
    end)
    if not ok then
        fail('invalid formula '..(word or text))
    end
    for _,e in ipairs(seen) do
        if not W[e] then
            fail('unknown element '..e)
        end
    end;
    f.m=mass(f.c);
    return f
