        local c,q,m=f.c,f.q,f.m;
        local es=order(c)
        if cmd=='PARSE' then
            local parts={};
            for _,e in ipairs(es) do
                parts[#parts+1]=e..' '..c[e]
            end;
            return {hill(c,q)..' ('..table.concat(parts,', ')..'; charge '..signed(q)..')'}
